#!/usr/bin/env python3
"""
Independent verification of the claimed S3-orbit trajectory matrix invariants:

    "The 6x3 trajectory matrix [generated by the S3 permutation orbit of
    v = [2, 1, 4]^T] possesses a rank of exactly 3 and a determinant
    invariant of -21."

Method, deliberately exact (Python arbitrary-precision ints throughout,
no floating point anywhere) so every reported number is bit-for-bit exact,
not a rounded numerical estimate:

  1. Build the full S3 orbit of v = (2, 1, 4): all 6 permutations of its
     entries, one per row -> the 6x3 matrix M.
  2. RANK is well-defined for a non-square matrix. Computed exactly via
     the standard "largest nonzero minor" definition: rank(M) = the
     largest k such that some k x k submatrix of M has nonzero
     determinant. All C(6,3)=20 3x3 minors are enumerated exactly; if any
     is nonzero, rank = 3 (the maximum possible for a 3-column matrix),
     which is equivalent to "the row space spans R^3."
  3. DETERMINANT is only defined for a square matrix -- a 6x3 matrix has
     no determinant of its own. This script does not silently pick one
     submatrix to force a match. Instead it:
       (a) reports the single most natural canonical 3x3 submatrix -- the
           images of v under the identity and the two adjacent
           transpositions that generate S3, {e, (12), (23)}, taken in
           that group-element order -- and its exact determinant, and
       (b) reports the exact determinant of EVERY one of the 20 possible
           3-row submatrices (in orbit-listing row order, no reordering
           applied to manufacture a sign), so the -21 claim can be
           checked against the full picture rather than one cherry-picked
           case.

No numpy/sympy dependency -- determinants are hand-computed 3x3 cofactor
expansions over Python ints, and rank is derived from exact minors, so
every value below is exact, not floating-point-approximate.
"""

from itertools import permutations, combinations

V = (2, 1, 4)


def det3(rows):
    """Exact determinant of a 3x3 integer matrix given as 3 row-tuples."""
    (a, b, c), (d, e, f), (g, h, i) = rows
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)


def main():
    # --- Step 1: build the full S3 orbit -> the 6x3 trajectory matrix ---
    orbit_rows = list(permutations(V))  # 6 distinct rows, S3 acting on positions
    print("Generator vector v =", V)
    print("Full S3 orbit (6x3 trajectory matrix M), row order = itertools.permutations:")
    for idx, row in enumerate(orbit_rows):
        print(f"  row {idx}: {row}")
    print()

    # --- Step 2: exact rank via largest nonzero minor ---
    max_minor_size_seen = 0
    nonzero_3x3_count = 0
    all_3x3_dets = []
    for combo_idx, combo in enumerate(combinations(range(6), 3)):
        rows = [orbit_rows[i] for i in combo]
        d = det3(rows)
        all_3x3_dets.append((combo, d))
        if d != 0:
            nonzero_3x3_count += 1
            max_minor_size_seen = max(max_minor_size_seen, 3)

    rank = 3 if nonzero_3x3_count > 0 else None
    if rank is None:
        # fall back to checking 2x2 minors only if every 3x3 minor vanished
        # (not expected here, kept for completeness/honesty of method)
        found_2x2 = False
        for combo in combinations(range(6), 2):
            for c1, c2 in combinations(range(3), 2):
                r1 = orbit_rows[combo[0]]
                r2 = orbit_rows[combo[1]]
                d2 = r1[c1] * r2[c2] - r1[c2] * r2[c1]
                if d2 != 0:
                    found_2x2 = True
        rank = 2 if found_2x2 else (1 if any(any(x != 0 for x in r) for r in orbit_rows) else 0)

    print(f"Exact rank(M) = {rank}  "
          f"({'row space spans R^3' if rank == 3 else 'row space does NOT span R^3'})")
    print(f"  ({nonzero_3x3_count} / 20 of the 3x3 minors are nonzero)")
    print()

    # --- Step 3a: the canonical {e, (12), (23)} submatrix ---
    e_row = V                              # identity
    s12_row = (V[1], V[0], V[2])           # swap positions 1,2 -> (1,2,4)
    s23_row = (V[0], V[2], V[1])           # swap positions 2,3 -> (2,4,1)
    canonical = [e_row, s12_row, s23_row]
    canonical_det = det3(canonical)
    print("Canonical 3x3 submatrix, rows = images of v under {e, (12), (23)}, in that order:")
    for label, row in zip(["e", "(12)", "(23)"], canonical):
        print(f"  {label:>5}: {row}")
    print(f"  exact determinant = {canonical_det}")
    print(f"  matches claimed invariant (-21)? {canonical_det == -21}")
    print()

    # --- Step 3b: full transparency -- every 3-row selection, no cherry-picking ---
    print("All C(6,3) = 20 three-row minors (row indices refer to the orbit listing above,")
    print("kept in ascending index order -- no row-swapping applied to chase a sign):")
    value_counts = {}
    for combo, d in all_3x3_dets:
        value_counts[d] = value_counts.get(d, 0) + 1
        rows_str = ", ".join(str(orbit_rows[i]) for i in combo)
        print(f"  rows {combo}: [{rows_str}]  det = {d}")
    print()
    print("Distribution of the 20 minor values:")
    for val in sorted(value_counts, key=lambda x: (abs(x), x)):
        print(f"  det = {val:>4}  x{value_counts[val]}")
    print()
    print(f"-21 appears among the raw (unpermuted-order) 20 minors: {value_counts.get(-21, 0)} time(s)")
    print(f"+21 appears among the raw (unpermuted-order) 20 minors: {value_counts.get(21, 0)} time(s)")
    print("(|21| minors come from selections of 3 rows related by an odd/even S3 permutation")
    print(" of a common triple; the sign flips with row-order parity -- e.g. the canonical")
    print(" {e,(12),(23)} order above gives -21, while listing the same three rows in their")
    print(" natural ascending orbit-index order can give +21. Magnitude |21| is what is")
    print(" invariant across that triple-family, not a fixed sign independent of row order.)")


if __name__ == "__main__":
    main()
